CREATE TABLE IF NOT EXISTS pengguna (id BIGSERIAL PRIMARY KEY, nama VARCHAR(140) NOT NULL, email VARCHAR(180) NOT NULL UNIQUE, no_hp VARCHAR(20) NOT NULL, password_hash VARCHAR(100) NOT NULL, peran VARCHAR(20) NOT NULL CHECK (peran IN ('USER','PEMILIK','SUPERADMIN')), aktif BOOLEAN NOT NULL DEFAULT TRUE, data_tambahan JSONB NOT NULL DEFAULT '{}'::jsonb, dibuat_pada TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS kos (id BIGSERIAL PRIMARY KEY, pemilik_id BIGINT NOT NULL REFERENCES pengguna(id), nama VARCHAR(140) NOT NULL, alamat TEXT NOT NULL, kode_pos VARCHAR(5) NOT NULL, aturan_kos TEXT NOT NULL DEFAULT '', tanggal_jatuh_tempo SMALLINT NOT NULL DEFAULT 5, status_verifikasi VARCHAR(24) NOT NULL DEFAULT 'MENUNGGU', catatan_verifikasi TEXT, aturan_denda JSONB NOT NULL DEFAULT '{"jenis":"HARIAN","nominalPerHari":10000,"masaTenggang":3,"batasMaksimal":150000}'::jsonb, dibuat_pada TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS kamar (id BIGSERIAL PRIMARY KEY, kos_id BIGINT NOT NULL REFERENCES kos(id) ON DELETE CASCADE, nomor VARCHAR(20) NOT NULL, tipe VARCHAR(20) NOT NULL, harga_bulanan BIGINT NOT NULL CHECK(harga_bulanan > 0), luas NUMERIC(6,2) NOT NULL DEFAULT 9, fasilitas JSONB NOT NULL DEFAULT '[]'::jsonb, status VARCHAR(20) NOT NULL DEFAULT 'KOSONG', UNIQUE(kos_id, nomor));
CREATE TABLE IF NOT EXISTS paket_sewa (id BIGSERIAL PRIMARY KEY, kos_id BIGINT NOT NULL REFERENCES kos(id) ON DELETE CASCADE, nama VARCHAR(20) NOT NULL, durasi_bulan SMALLINT NOT NULL, persen_diskon NUMERIC(5,2) NOT NULL DEFAULT 0, aktif BOOLEAN NOT NULL DEFAULT TRUE, UNIQUE(kos_id, nama));
CREATE TABLE IF NOT EXISTS booking (id BIGSERIAL PRIMARY KEY, penyewa_id BIGINT NOT NULL REFERENCES pengguna(id), kamar_id BIGINT NOT NULL REFERENCES kamar(id), paket_id BIGINT NOT NULL REFERENCES paket_sewa(id), tanggal_masuk DATE NOT NULL, tanggal_selesai DATE NOT NULL, total_sewa BIGINT NOT NULL, status VARCHAR(20) NOT NULL DEFAULT 'MENUNGGU', aturan_disetujui_pada TIMESTAMPTZ NOT NULL DEFAULT NOW(), alasan_tolak TEXT, dibuat_pada TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS tagihan (id BIGSERIAL PRIMARY KEY, booking_id BIGINT NOT NULL REFERENCES booking(id), periode DATE NOT NULL, jatuh_tempo DATE NOT NULL, subtotal_item BIGINT NOT NULL DEFAULT 0, denda BIGINT NOT NULL DEFAULT 0, total BIGINT NOT NULL DEFAULT 0, terbayar BIGINT NOT NULL DEFAULT 0, status VARCHAR(30) NOT NULL DEFAULT 'BELUM_BAYAR', meteran_awal NUMERIC(10,1), meteran_akhir NUMERIC(10,1), UNIQUE(booking_id, periode));
CREATE TABLE IF NOT EXISTS item_tagihan (id BIGSERIAL PRIMARY KEY, tagihan_id BIGINT NOT NULL REFERENCES tagihan(id) ON DELETE CASCADE, jenis VARCHAR(20) NOT NULL, keterangan VARCHAR(180) NOT NULL, subtotal BIGINT NOT NULL, meteran_awal NUMERIC(10,1), meteran_akhir NUMERIC(10,1), tarif_per_unit BIGINT, satuan VARCHAR(20));
CREATE TABLE IF NOT EXISTS pembayaran (id BIGSERIAL PRIMARY KEY, tagihan_id BIGINT NOT NULL REFERENCES tagihan(id), metode VARCHAR(20) NOT NULL, jumlah BIGINT NOT NULL CHECK(jumlah > 0), tanggal TIMESTAMPTZ NOT NULL DEFAULT NOW(), status VARCHAR(30) NOT NULL DEFAULT 'MENUNGGU_VERIFIKASI', bank_asal VARCHAR(80), nama_pengirim VARCHAR(140), bukti_url TEXT, catatan_verifikasi TEXT);
CREATE TABLE IF NOT EXISTS pengajuan_penundaan (id BIGSERIAL PRIMARY KEY, tagihan_id BIGINT NOT NULL UNIQUE REFERENCES tagihan(id), tanggal_diminta DATE NOT NULL, alasan TEXT NOT NULL, status VARCHAR(20) NOT NULL DEFAULT 'MENUNGGU', catatan_pemilik TEXT, dibuat_pada TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS keluhan (id BIGSERIAL PRIMARY KEY, booking_id BIGINT NOT NULL REFERENCES booking(id), kategori VARCHAR(24) NOT NULL, deskripsi TEXT NOT NULL, status VARCHAR(20) NOT NULL DEFAULT 'DILAPORKAN', tanggapan_pemilik TEXT, dibuat_pada TIMESTAMPTZ NOT NULL DEFAULT NOW(), diperbarui_pada TIMESTAMPTZ NOT NULL DEFAULT NOW());
